'use strict';

// MODULES //

var normalize = require( './normalize.js' );
var setGlyph = require( './glyph.js' );
var label = require( './label.js' );

/**
* Method to draw the bar.
*
* @private
* @name renderAxis
* @param {Array} data - axis data in form of [ x, y, z, w ]
* @param {Array} frmt - frm string for the axis
* @param {Array} stride - stride on each tick
* @returns {void}
*/
function renderAxis( data, frmt, stride ) {
	var arr;
	var obj;
	var mxX;

	// var mxY;
	// var mxZ;
	// var mxW;
	var r;
	var c;
	var i;

	// X axis
	r = 2;
	c = 0;
	obj = normalize( data[ 0 ], frmt, 'graphemes' );
	arr = obj.data;
	mxX = obj.max;
	for ( i = 0; i < arr.length; i++ ) {
		label( r, c, arr[ i ], true );
		setGlyph( r, c, this.HorizontelTicsGlyph, true );
		r += stride[ 0 ];
	}

	// Y axis
	r = 0;
	c = mxX + 2;
	obj = normalize( data[ 1 ], frmt, 'graphemes' );
	arr = obj.data[ 1 ];

	// mxY = obj.max;
	for ( i = 0; i < arr.length; i++ ) {
		label( r, c, arr[ i ], true );
		setGlyph( r, c, this.verticalTicsGlyph, true );
		c += stride[ 1 ];
	}

	// Z Axis
	r = 2;
	c = this._width + mxX;
	obj = normalize( data[ 0 ], frmt, 'graphemes' );
	arr = obj.data;

	// mxZ = obj.max;
	for ( i = 0; i < arr.length; i++ ) {
		label( r, c, arr[ i ], true );
		setGlyph( r, c, this.HorizontelTicsGlyph, true );
		r += stride[ 2 ];
	}

	// W axis
	r = this._height + 2;
	c = mxX + 2;
	obj = normalize( data[ 1 ], frmt, 'graphemes' );
	arr = obj.data[ 1 ];

	// mxW = obj.max;
	for ( i = 0; i < arr.length; i++ ) {
		label( r, c, arr[ i ], true );
		setGlyph( r, c, this.verticalTicsGlyph, true );
		c += stride[ 3 ];
	}

	this._plotArea.col = mxX;
	this._plotArea.row = 2;
}

module.exports = renderAxis;
